#!/usr/bin/env Rscript
# Patient-level downstream analysis using the reviewed formal 7-cluster annotation.
suppressPackageStartupMessages({ library(Seurat); library(SeuratObject); library(Matrix); library(GSVA); library(ggplot2); library(patchwork); library(digest) })
project_root <- "D:/Users/lstsw/Documents/Adipose_derived stromal_metabolic niches/adipose_stromal_metabolic_niche_lit/public_data_analysis/GSE161529_ASC_P_validation"
source(file.path(project_root, "scripts", "utils_GSE161529_ASC_P.R"))
cfg <- list(source_rds=file.path(dirname(project_root),"data","processed","GSE161529_figshare","SeuratObject_ERTotal.rds"), formal_rds=file.path(project_root,"outputs","ERTotal_cluster1_TNK_Harmony_optimized_formal_annotation","ERTotal_cluster1_Harmony_optimized_formal_annotation.rds"), caf_map=file.path(project_root,"tables","ERTotal_cluster_annotation_map_approved.tsv"), patient_map=file.path(project_root,"tables","ThreeTumor_sample_patient_mapping.tsv"), pam50=file.path(project_root,"outputs","ThreeTumor_PAM50_LumB_similarity","ThreeTumor_PAM50_centroid_correlations_by_patient.tsv"), manifest=file.path(project_root,"outputs","ThreeTumor_PAM50_LumB_similarity","ThreeTumor_PAM50_primary_anchor_manifest.tsv"), output_dir=file.path(project_root,"outputs","ERTotal_CD4_Tconv_Treg_formalcluster_LumB_anchor"), min_tconv=20L, min_caf=20L, min_patients=5L, seed=20260717L, overwrite=identical(Sys.getenv("ERTOTAL_FORMAL_CD4_OVERWRITE"),"1"))
assert <- function(x,m) if(!isTRUE(x)) stop(m,call.=FALSE)
out <- function(x) file.path(cfg$output_dir,x)
write_tsv <- function(x,n) write.table(x,out(n),sep="\t",quote=FALSE,row.names=FALSE,na="")
sha <- function(x) digest(file=x,algo="sha256")
safe_z <- function(x) { z<-as.numeric(scale(x)); z[!is.finite(z)]<-0; z }
ssgsea <- function(x,sets) { if("ssgseaParam" %in% getNamespaceExports("GSVA")) return(as.matrix(GSVA::gsva(GSVA::ssgseaParam(exprData=x,geneSets=sets,minSize=2,maxSize=Inf,normalize=TRUE),verbose=FALSE))); as.matrix(GSVA::gsva(expr=as.matrix(x),gset.idx.list=sets,method="ssgsea",kcdf="Gaussian",min.sz=2,max.sz=Inf,parallel.sz=1,ssgsea.norm=TRUE,verbose=FALSE)) }
sp <- function(d,x,y,family,label) { ok<-is.finite(d[[x]])&is.finite(d[[y]]); if(sum(ok)<cfg$min_patients||length(unique(d[[x]][ok]))<2L||length(unique(d[[y]][ok]))<2L) return(data.frame(family=family,x=x,y=y,n=sum(ok),rho=NA_real_,p_value=NA_real_,interpretation=label)); q<-suppressWarnings(cor.test(d[[x]][ok],d[[y]][ok],method="spearman",exact=FALSE)); data.frame(family=family,x=x,y=y,n=sum(ok),rho=unname(q$estimate),p_value=q$p.value,interpretation=label) }
main <- function() {
  required <- unlist(cfg[c("source_rds","formal_rds","caf_map","patient_map","pam50","manifest")]); assert(all(file.exists(required)),"Required input is missing.")
  dir.create(cfg$output_dir,recursive=TRUE,showWarnings=FALSE); if(length(list.files(cfg$output_dir,all.files=TRUE,no..=TRUE))&&!cfg$overwrite) stop("Output exists; set ERTOTAL_FORMAL_CD4_OVERWRITE=1 to rerun.")
  set.seed(cfg$seed); src<-load_seurat_object(cfg$source_rds); meta<-safe_meta_data(src); counts<-get_rna_matrix(src,"counts")
  pm<-read.delim(cfg$patient_map,stringsAsFactors=FALSE,colClasses="character"); pm<-pm[pm$dataset=="ERTotal",]; patient<-paste0("ERTotal__",pm$patient_id[match(as.character(meta$group),pm$group_id)]); names(patient)<-rownames(meta); assert(!anyNA(patient),"Unmapped ERTotal patient.")
  caf<-read.delim(cfg$caf_map,stringsAsFactors=FALSE); flag<-tolower(trimws(as.character(caf$candidate_denominator)))%in%c("true","1","yes","y"); cf<-flag[match(as.character(meta$seurat_clusters),as.character(caf$cluster))]; assert(!anyNA(cf),"CAF map does not cover source clusters.")
  asc_genes<-c("ENG","THY1","NT5E","PDGFRA","VCAM1","MCAM"); assert(all(asc_genes%in%rownames(counts)),"ASC_P panel incomplete."); asc<-cf & Matrix::colSums(counts[asc_genes,,drop=FALSE]>0)>=3L; names(asc)<-colnames(counts); names(cf)<-colnames(counts)
  obj<-readRDS(cfg$formal_rds); om<-obj[[]]; assert(all(c("CD4_analysis_role","formal_short_label","patient_id")%in%colnames(om)),"Formal annotation metadata is missing.")
  tconv<-colnames(obj)[as.character(obj$CD4_analysis_role)=="Primary_CD4_Tconv"]; treg<-colnames(obj)[as.character(obj$CD4_analysis_role)=="Primary_Treg"]; assert(length(tconv)==1640L&&length(treg)==1006L,"Formal cluster roles do not have expected cell counts.")
  dat<-LayerData(obj,assay="RNA",layer="data"); sets0<-list(ANERGY=c("RNF128","CBLB","ITCH","EGR2","EGR3","DGKA","NR4A1","NR4A2","NR4A3","TOX","PDCD1","CTLA4","LAG3","HAVCR2"),ACTIVATION=c("CD69","IL2RA","IFNG","TNF","GZMB","PRF1"),EXHAUSTION=c("PDCD1","LAG3","TIGIT","HAVCR2","TOX","BATF","CXCL13")); sets<-lapply(sets0,intersect,rownames(dat)); assert(all(lengths(sets)>=2L),"Insufficient genes for one state program.")
  sc<-ssgsea(dat[,tconv,drop=FALSE],sets); cell_scores<-data.frame(cell_id=tconv,patient_id=as.character(obj$patient_id[tconv]),ANERGY_ssGSEA=as.numeric(sc["ANERGY",]),ACTIVATION_ssGSEA=as.numeric(sc["ACTIVATION",]),EXHAUSTION_ssGSEA=as.numeric(sc["EXHAUSTION",]),stringsAsFactors=FALSE); cell_scores$ANERGY_z<-safe_z(cell_scores$ANERGY_ssGSEA); cell_scores$ACTIVATION_z<-safe_z(cell_scores$ACTIVATION_ssGSEA); cell_scores$EXHAUSTION_z<-safe_z(cell_scores$EXHAUSTION_ssGSEA); write_tsv(cell_scores,"ERTotal_formalcluster_CD4_Tconv_cell_state_scores.tsv")
  pids<-sort(unique(patient)); rows<-lapply(pids,function(pid){ pc<-names(patient)[patient==pid]; tc<-cell_scores[cell_scores$patient_id==pid,,drop=FALSE]; tr<-sum(as.character(obj$patient_id[treg])==pid); ca<-pc[cf[pc]]; ac<-ca[asc[ca]]; cd4n<-nrow(tc)+tr; data.frame(patient_id=pid,caf_n=length(ca),asc_candidate_n=length(ac),asc_candidate_fraction=if(length(ca))length(ac)/length(ca) else NA_real_,tconv_n=nrow(tc),treg_n=tr,formal_CD4_n=cd4n,treg_fraction_of_formal_CD4=if(cd4n)tr/cd4n else NA_real_,ANERGY_median=if(nrow(tc))median(tc$ANERGY_ssGSEA) else NA_real_,ACTIVATION_median=if(nrow(tc))median(tc$ACTIVATION_ssGSEA) else NA_real_,EXHAUSTION_median=if(nrow(tc))median(tc$EXHAUSTION_ssGSEA) else NA_real_) }); tab<-do.call(rbind,rows); tab$eligible_joint<-tab$tconv_n>=cfg$min_tconv&tab$caf_n>=cfg$min_caf
  man<-read.delim(cfg$manifest,stringsAsFactors=FALSE); assert(nrow(man)==1L&&toupper(man$artifact_sha256)==toupper(sha(cfg$pam50)),"PAM50 primary anchor hash mismatch."); pam<-read.delim(cfg$pam50,stringsAsFactors=FALSE); pam<-pam[pam$dataset=="ERTotal",c("patient_id","LumB_correlation","nearest_centroid_reported"),drop=FALSE]; tab<-merge(tab,pam,by="patient_id",all.x=TRUE,sort=FALSE); assert(!anyNA(tab$LumB_correlation),"Missing ERTotal PAM50 anchor."); tab$LumB_anchor_group<-ifelse(tab$nearest_centroid_reported=="LumB","nearest_LumB","other_ERTotal"); write_tsv(tab,"ERTotal_formalcluster_patient_ASC_P_CAF_CD4_state_LumB_anchor.tsv")
  e<-tab[tab$eligible_joint,,drop=FALSE]; a<-do.call(rbind,list(sp(e,"asc_candidate_fraction","ANERGY_median","primary","ASC_P-like CAF fraction versus formal-cluster CD4 Tconv anergy"),sp(e,"asc_candidate_fraction","EXHAUSTION_median","secondary","ASC_P-like CAF fraction versus CD4 Tconv exhaustion"),sp(e,"asc_candidate_fraction","ACTIVATION_median","secondary","ASC_P-like CAF fraction versus CD4 Tconv activation"),sp(e,"asc_candidate_fraction","treg_fraction_of_formal_CD4","secondary","ASC_P-like CAF fraction versus formal-cluster Treg fraction"),sp(e,"LumB_correlation","asc_candidate_fraction","LumB_anchor","LumB resemblance versus ASC_P-like CAF fraction"),sp(e,"LumB_correlation","ANERGY_median","LumB_anchor","LumB resemblance versus CD4 Tconv anergy"))); a$p_adjust_holm_within_family<-NA_real_; for(f in unique(a$family)){i<-a$family==f&is.finite(a$p_value);a$p_adjust_holm_within_family[i]<-p.adjust(a$p_value[i],"holm")}; write_tsv(a,"ERTotal_formalcluster_patient_level_ASC_P_CD4_LumB_associations.tsv")
  label<-function(x,y){z<-a[a$x==x&a$y==y,,drop=FALSE];if(!nrow(z)||!is.finite(z$rho))"Descriptive only" else sprintf("Spearman rho = %.2f; P = %.3g; n = %d",z$rho,z$p_value,z$n)}
  p1<-DimPlot(obj,reduction="umap_optimized",group.by="formal_short_label",pt.size=.2)+coord_fixed()+labs(title="A. Formal 7-cluster annotation",colour=NULL)+theme_classic(base_size=10)+theme(legend.position="bottom",legend.text=element_text(size=7))+guides(colour=guide_legend(nrow=2,byrow=TRUE)); p2<-ggplot(e,aes(asc_candidate_fraction,ANERGY_median,colour=LumB_correlation))+geom_point(size=3)+scale_colour_gradient2(low="#2166AC",mid="white",high="#B2182B",midpoint=0)+labs(title="B. ASC_P-like CAF abundance and CD4 Tconv anergy",subtitle=label("asc_candidate_fraction","ANERGY_median"),x="ASC_P-like candidates / CAF",y="Patient median ANERGY ssGSEA",colour="LumB r")+theme_classic(base_size=10); p3<-ggplot(e,aes(asc_candidate_fraction,treg_fraction_of_formal_CD4,colour=LumB_correlation))+geom_point(size=3)+scale_colour_gradient2(low="#2166AC",mid="white",high="#B2182B",midpoint=0)+labs(title="C. ASC_P-like CAF abundance and Treg fraction",subtitle=label("asc_candidate_fraction","treg_fraction_of_formal_CD4"),x="ASC_P-like candidates / CAF",y="Treg / (Tconv + Treg)",colour="LumB r")+theme_classic(base_size=10); fig<-p1/(p2|p3)+plot_layout(heights=c(1.1,1)); ggsave(out("Fig_FormalCD4_LumB.png"),fig,width=14,height=12,dpi=320,bg="white"); ggsave(out("Fig_FormalCD4_LumB.pdf"),fig,width=14,height=12,bg="white")
  writeLines(c("# Formal-cluster CD4 Tconv/Treg state analysis","",paste0("Eligible patients: ",nrow(e),"/",nrow(tab)),paste0("CD4 Tconv cells (cluster 1): ",length(tconv)),paste0("Treg cells (cluster 2): ",length(treg)),"Statistical unit: patient. Cell-level ssGSEA is summarized by patient median.","Cluster 1 and 2 assignments derive from reviewed 7-cluster FindAllMarkers annotation; old rule-defined analysis is not used.",paste0("Input SHA256: ",paste(paste(basename(required),vapply(required,sha,character(1)),sep="="),collapse="; "))),out("ERTotal_formalcluster_CD4_state_LumB_anchor_RUN_REPORT.md")); writeLines(capture.output(sessionInfo()),out("ERTotal_formalcluster_CD4_state_LumB_anchor_sessionInfo.txt"))
}
main()
